const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];
const falta = ["CHATWOOT_DOMAIN", "CHATWOOT_API_TOKEN", "CHATWOOT_ACCOUNT_ID"].filter(k => !$env[k]);
if (falta.length) return fail(500, 'PENDENTE_CONFIGURACAO_CHATWOOT: variáveis ausentes no ambiente do Harmonia: ' + falta.join(', '), 'PENDENTE_CONFIGURACAO_CHATWOOT');
if (!/^\d+$/.test(String($env.CHATWOOT_ACCOUNT_ID))) return fail(500, 'PENDENTE_CONFIGURACAO_CHATWOOT: CHATWOOT_ACCOUNT_ID não é numérico', 'PENDENTE_CONFIGURACAO_CHATWOOT');
return [{ json: { ok: true } }];

const canalDe = (ch) => ({
  'Channel::Whatsapp': 'whatsapp', 'Channel::FacebookPage': 'facebook', 'Channel::Instagram': 'instagram',
  'Channel::WebWidget': 'website', 'Channel::Telegram': 'telegram', 'Channel::Sms': 'sms', 'Channel::TwilioSms': 'sms'
}[ch] || 'outro');
const vistos = new Set(); const conversas = [];
for (const it of $input.all()) {
  const lista = (it.json.data && it.json.data.payload) || [];
  for (const c of lista) {
    if (vistos.has(c.id)) continue; vistos.add(c.id);
    const s = (c.meta && c.meta.sender) || {};
    const ult = c.last_non_activity_message || (c.messages && c.messages[c.messages.length - 1]) || null;
    conversas.push({
      id: c.id,
      nome: s.name || s.phone_number || s.email || ('Conversa ' + c.id),
      canal: canalDe(String((c.meta && c.meta.channel) || '')),
      nao_lida: Number(c.unread_count || 0) > 0,
      status: c.status,
      contato: s.phone_number || null,
      ultima_mensagem: (ult && ult.content) || null,
      atualizado_em: c.last_activity_at ? new Date(c.last_activity_at * 1000).toISOString() : null
    });
  }
}
return [{ json: { status: 200, body: { conversas } } }];

const it = $input.first().json || {};
const e = it.error || it;
const raw = String(e.description || e.message || 'erro desconhecido');
const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
const clean = raw.replace(/https?:\/\/\S+/g, '[url]').replace(/(token|api_access_token|authorization)\S*/gi, '[omitido]').slice(0, 300);
const status = upstream === 404 ? 404 : 502;
const m = "Falha ao consultar conversas no Harpa" + (upstream ? ' (HTTP ' + upstream + ')' : '') + (true ? ': ' + clean : '');
return [{ json: { status, body: { sucesso: false, erro: m, message: m, origem: "harpa" } } }];
